// PHASE: Standard 14 metrics — exact per-glyph widths.
//
// GENERATED DATA: the width arrays below were produced by a codegen pass over
// the canonical Adobe Core 14 AFM files (the URW base-35 metrics distributed
// with Ghostscript/matplotlib, metrically identical to Adobe's originals) —
// glyph names mapped to WinAnsi codes via the Adobe Glyph List. Do not edit
// the numbers by hand; regenerate from the AFMs.

using System;

namespace Chuvadi.Pdf.Fonts.Rendering;

/// <summary>
/// Exact per-glyph advance-width metrics for the PDF Standard 14 fonts in
/// 1/1000-em font design units.
/// </summary>
/// <remarks>
/// <para>
/// Used by <see cref="RenderableFont"/> (and, through
/// <see cref="Standard14GlyphWidths"/>, the display-list width resolver) as
/// the width source for Standard 14 fonts when a PDF font dictionary omits
/// its /Widths array — as §9.6.2.2 permits for these fonts. Works even when
/// <see cref="Standard14Outlines.BundleAvailable"/> is false — in that case
/// glyphs cannot be drawn, but layout and selection still produce correct
/// positions for the reader-app text layer.
/// </para>
/// <para>
/// The twelve text fonts are indexed by WinAnsi (cp1252) character code;
/// Symbol and ZapfDingbats are indexed by their built-in encodings. Codes
/// with no glyph fall back to a per-font average so a stray byte never
/// collapses layout.
/// </para>
/// <para>
/// Units: 1/1000 of an em square. To convert the returned value to PDF
/// user-space points for a given <c>pointSize</c>, multiply by
/// <c>pointSize / 1000.0</c>.
/// </para>
/// </remarks>
public static class Standard14Widths
{
    /// <summary>The units-per-em value used by all Standard 14 widths (1000).</summary>
    public const int UnitsPerEm = 1000;

    /// <summary>
    /// Returns the advance width of <paramref name="charCode"/> in
    /// <paramref name="fontName"/> in 1/1000 em units.
    /// </summary>
    /// <param name="fontName">A Standard 14 PostScript font name (e.g. "Helvetica").</param>
    /// <param name="charCode">
    /// A WinAnsi character code (0–255) for the text fonts, or the built-in
    /// encoding code for Symbol and ZapfDingbats.
    /// </param>
    /// <returns>
    /// The exact Adobe AFM advance width in 1/1000 em, or the per-font
    /// average when the code has no glyph. For non-Standard 14 fonts returns
    /// the em-half default of 500.
    /// </returns>
    /// <exception cref="ArgumentNullException">
    /// Thrown when <paramref name="fontName"/> is null.
    /// </exception>
    public static int GetWidth(string fontName, int charCode)
    {
        ArgumentNullException.ThrowIfNull(fontName);

        ushort[]? table = TableFor(fontName);

        if (table is null)
        {
            return 500;
        }

        if (charCode >= 32 && charCode <= 255)
        {
            int width = table[charCode - 32];

            if (width > 0)
            {
                return width;
            }
        }

        return GetAverageWidth(fontName);
    }

    /// <summary>
    /// Returns true when <paramref name="fontName"/> matches one of the
    /// 14 Standard PostScript font names.
    /// </summary>
    /// <exception cref="ArgumentNullException">
    /// Thrown when <paramref name="fontName"/> is null.
    /// </exception>
    public static bool IsStandard14(string fontName)
    {
        ArgumentNullException.ThrowIfNull(fontName);
        return TableFor(fontName) is not null;
    }

    private static ushort[]? TableFor(string fontName) => fontName switch
    {
        "Times-Roman" => TimesRoman,
        "Times-Bold" => TimesBold,
        "Times-Italic" => TimesItalic,
        "Times-BoldItalic" => TimesBoldItalic,
        "Helvetica" => Helvetica,
        "Helvetica-Bold" => HelveticaBold,
        "Helvetica-Oblique" => HelveticaOblique,
        "Helvetica-BoldOblique" => HelveticaBoldOblique,
        "Courier" => Courier,
        "Courier-Bold" => CourierBold,
        "Courier-Oblique" => CourierOblique,
        "Courier-BoldOblique" => CourierBoldOblique,
        "Symbol" => Symbol,
        "ZapfDingbats" => ZapfDingbats,
        _ => null,
    };

    private static int GetAverageWidth(string fontName) => fontName switch
    {
        "Helvetica" or "Helvetica-Oblique" => 556,
        "Helvetica-Bold" or "Helvetica-BoldOblique" => 600,
        "Times-Roman" or "Times-Italic" => 500,
        "Times-Bold" or "Times-BoldItalic" => 556,
        "Courier" or "Courier-Bold" or "Courier-Oblique" or "Courier-BoldOblique" => 600,
        "Symbol" => 500,
        "ZapfDingbats" => 750,
        _ => 500,
    };

